tool_and_message_events.command:
/bin/bash -lc "node <<'NODE'
const { spawnSync } = require('node:child_process');
const cases = [['locate', ['run', 'locate']], ['start', ['start', '--', '5']], ['drain', ['run', 'drain']]];
for (const options of [process.env.NODE_OPTIONS, '--no-require-module', '--no-strip-types']) {
  for (const [name, args] of cases) {
    const env = { ...process.env, npm_config_offline: 'true', npm_config_update_notifier: 'false', npm_config_logs_max: '0' };
    if (options === undefined) delete env.NODE_OPTIONS;
    else env.NODE_OPTIONS = options;
    const started = performance.now();
    const result = spawnSync('npm', ['--silent', ...args], { env, encoding: 'utf8' });
    console.log(JSON.stringify({ options: options ?? '(unset)', name, ms: Math.round(performance.now() - started),
      exit: result.status, signal: result.signal, stdout: result.stdout, stderr: result.stderr,
      error: result.error?.code }));
  }
}
NODE
